import os
from google import genai
from google.cloud import aiplatform
from google.cloud import translate_v3 as translate
from google.cloud import texttospeech


def get_gemini_client(api_key=None):
    api_key = api_key or os.environ.get("GOOGLE_API_KEY")
    if not api_key:
        raise ValueError("GOOGLE_API_KEY not found in environment variables or config.")
    return genai.Client(api_key=api_key)


def get_vertex_ai_prediction_client(project_id=None, location=None):
    project_id = project_id or os.environ.get("GOOGLE_CLOUD_PROJECT")
    location = location or os.environ.get("GOOGLE_CLOUD_REGION")
    if not project_id or not location:
        raise ValueError("GOOGLE_CLOUD_PROJECT and GOOGLE_CLOUD_REGION must be set for Vertex AI.")
    return aiplatform.gapic.PredictionServiceClient(client_options={"api_endpoint": f"{location}-aiplatform.googleapis.com"})

def get_translate_client(project_id=None):
    project_id = project_id or os.environ.get("GOOGLE_CLOUD_PROJECT")
    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT must be set for Translation API.")
    return translate.TranslationServiceClient()

def get_text_to_speech_client():
    return texttospeech.TextToSpeechClient()

from dataclasses import dataclass
from typing import Dict, Any, List

@dataclass
class LLMRequest:
    text: str
    model: str = "gemini-2.5-flash"
    temperature: float = 0.7
    max_output_tokens: int = 1024

@dataclass
class LLMResponse:
    text: str

@dataclass
class ContextualLLMRequest(LLMRequest):
    context: str
    question: str

@dataclass
class JsonExtractionLLMRequest(LLMRequest):
    format_instructions: str

@dataclass
class SafetyCheckRequest:
    text: str

@dataclass
class TranslateRequest:
    text: str
    target_language_code: str
    source_language_code: str = "en"

@dataclass
class EmbeddingRequest:
    text: List[str]
    model: str = "text-embedding-004"

@dataclass
class SpokenBriefRequest:
    text: str
    language_code: str = "en-US"
    voice_name: str = "en-US-Standard-A"

import os
from google import genai
from model_client import get_gemini_client

def extract_json(payload, config=None):
    config = config or {}
    text = payload["text"]
    format_instructions = payload.get("format_instructions", "Extract the relevant information as a JSON object.")

    prompt = f"""{format_instructions}

Here is the text:
{text}

Please respond with only the JSON object.
"""

    client = get_gemini_client(api_key=config.get("api_key"))
    response = client.models.generate_content(model="gemini-2.5-flash", contents=prompt)

    # Attempt to parse the response as JSON. If it fails, return the raw text.
    try:
        import json
        return {"json_output": json.loads(response.text.strip())}
    except json.JSONDecodeError:
        return {"json_output": response.text.strip()}

import os
from google import genai
from model_client import get_gemini_client

def stream_completion(payload, config=None):
    config = config or {}
    text = payload["text"]

    client = get_gemini_client(api_key=config.get("api_key"))
    responses = client.models.generate_content(model="gemini-2.5-flash", contents=text, stream=True)

    streamed_output = []
    for chunk in responses:
        streamed_output.append(chunk.text)
    return {"streamed_text": "".join(streamed_output)}
